        {shape==='floating-islands'&&<><label htmlFor="island-width">Island reference width (m)</label><input id="island-width" type="number" value={islandWidth} onChange={e=>setIslandWidth(e.target.value)}/><label htmlFor="island-length">Island reference length (m)</label><input id="island-length" type="number" value={islandLength} onChange={e=>setIslandLength(e.target.value)}/><label htmlFor="island-thickness">Island thickness (m)</label><input id="island-thickness" type="number" value={islandThickness} onChange={e=>setIslandThickness(e.target.value)}/><label htmlFor="island-seed">Island outline seed</label><input id="island-seed" type="number" value={islandSeed} onChange={e=>setIslandSeed(e.target.value)}/><label htmlFor="island-detail">Island numerical detail</label><select id="island-detail" value={resolution} onChange={e=>setResolution(Number(e.target.value) as 128|256)}><option value="128">N128 · 147,458 shared samples</option><option value="256">N256 · 589,826 shared samples</option></select><p className="hint">Width 10,000–1,000,000,000 m; length 0.75–1.5 × width; thickness 0.25–0.65 × width. The width and length set reference scales; the outline determines the actual bounds. The seed chooses a stable irregular outline. Elevations color the physical boundary; advanced displacement comes later.</p>{islandValid&&<p className="hint">Island size: {islandBounds}.</p>}{!islandValid&&<p role="status">Enter supported island dimensions and a nonnegative integer seed.</p>}</>}
